def dump(name,obj):
 p=OUT/name; p.parent.mkdir(parents=True,exist_ok=True); p.write_text(json.dumps(obj,indent=2,sort_keys=True)+'\n')
def sha(s): return hashlib.sha256(s.encode()).hexdigest()
def source(i,title,url,authority,effective,section,excerpt,published=None):
 return {'id':i,'title':title,'url':url,'authority':authority,'effective_date':effective,'retrieved_at':RETRIEVED,'published_or_updated':published or effective,'section':section,'excerpt':excerpt,'extraction_sha256':sha(excerpt)}
def rule(i,pathways,topic,status,authority,value,conditions,sources,section):
 return {'rule_id':i,'pathway_ids':pathways,'topic':topic,'status':status,'authority_class':authority,'value':value,'conditions':conditions,'source_ids':sources,'statutory_section':section,'parcel_conclusion':False}

